#include <vector>
#include <map>
#include <numeric>

class Solution {
public:
    long long countTrapezoids(std::vector<std::vector<int>>& segments) {
        std::map<std::pair<int, int>, std::vector<long long>> slope_groups;

        for (const auto& s : segments) {
            int x1 = s[0], y1 = s[1], x2 = s[2], y2 = s[3];
            int dx = x2 - x1, dy = y2 - y1;
            int g = std::gcd(dx, dy);
            dx /= g;
            dy /= g;
            if (dx < 0 || (dx == 0 && dy < 0)) {
                dx = -dx;
                dy = -dy;
            }
            long long c = (long long)dy * x1 - (long long)dx * y1;
            slope_groups[{dy, dx}].push_back(c);
        }

        long long total = 0;
        for (const auto& [slope, intercepts] : slope_groups) {
            std::map<long long, int> counts;
            for (long long c : intercepts) counts[c]++;

            long long running_sum = 0;
            for (const auto& [c, count] : counts) {
                total += running_sum * count;
                running_sum += count;
            }
        }

        return total;
    }
};

import java.util.*;

class Solution {
    public long countTrapezoids(int[][] segments) {
        Map<String, List<Long>> slopeGroups = new HashMap<>();

        for (int[] s : segments) {
            int x1 = s[0], y1 = s[1], x2 = s[2], y2 = s[3];
            int dx = x2 - x1, dy = y2 - y1;
            int g = gcd(Math.abs(dx), Math.abs(dy));
            if (g != 0) {
                dx /= g;
                dy /= g;
            }
            if (dx < 0 || (dx == 0 && dy < 0)) {
                dx = -dx;
                dy = -dy;
            }
            long c = (long) dy * x1 - (long) dx * y1;
            String slopeKey = dy + "/" + dx;
            slopeGroups.computeIfAbsent(slopeKey, k -> new ArrayList<>()).add(c);
        }

        long total = 0;
        for (List<Long> intercepts : slopeGroups.values()) {
            Map<Long, Integer> counts = new HashMap<>();
            for (long c : intercepts) counts.put(c, counts.getOrDefault(c, 0) + 1);

            long runningSum = 0;
            for (int count : counts.values()) {
                total += runningSum * count;
                runningSum += count;
            }
        }

        return total;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
}

/**
 * @param {number[][]} segments
 * @return {number}
 */
var countTrapezoids = function(segments) {
    const gcd = (a, b) => {
        a = Math.abs(a);
        b = Math.abs(b);
        while (b !== 0) {
            const t = b;
            b = a % b;
            a = t;
        }
        return a;
    };

    const slopeGroups = new Map();

    for (const [x1, y1, x2, y2] of segments) {
        let dx = x2 - x1, dy = y2 - y1;
        const g = gcd(dx, dy);
        if (g !== 0) {
            dx = Math.floor(dx / g);
            dy = Math.floor(dy / g);
        }
        if (dx < 0 || (dx === 0 && dy < 0)) {
            dx = -dx;
            dy = -dy;
        }
        const c = dy * x1 - dx * y1;
        const key = `${dy}/${dx}`;
        if (!slopeGroups.has(key)) slopeGroups.set(key, []);
        slopeGroups.get(key).push(c);
    }

    let total = 0;
    for (const intercepts of slopeGroups.values()) {
        const counts = new Map();
        for (const c of intercepts) counts.set(c, (counts.get(c) || 0) + 1);

        let runningSum = 0;
        for (const count of counts.values()) {
            total += runningSum * count;
            runningSum += count;
        }
    }

    return total;
};
